public class BuyReplacementReadinessPolicyNonActivationBoundaryTest {@Test public void remainsOutsideRuntimeAuthority()throws Exception{Path r=root();String[] names={"CompanionBuyReplacementReadinessPolicy","BuyReplacementReadinessAssessment"};for(String f:new String[]{"companion/src/main/java/com/flippingfriend/companion/CompanionService.java","companion/src/main/java/com/flippingfriend/companion/CompanionMain.java","companion/src/main/java/com/flippingfriend/companion/ApiServer.java","src/main/java/com/flippingfriend/companion/CompanionClient.java","src/main/java/com/flippingfriend/FlippingFriendPlugin.java","src/main/java/com/flippingfriend/model/SuggestionEngine.java"}){String s=Files.readString(r.resolve(f),StandardCharsets.UTF_8);for(String n:names)assertFalse(s.contains(n));}}private static Path root(){Path p=Path.of("").toAbsolutePath();while(p!=null&&!Files.exists(p.resolve("settings.gradle")))p=p.getParent();return p;}}
